// public/finderEngine.js
// ---------------------------------------------------------------------------
// Pure, data-driven matching logic. No Wix APIs in here, so it runs in Velo
// (backend or page) and in plain Node for tests.
//
// Flow:  getNextStep(records, state)   -> next question OR { done: true }
//        chooseOption(records, state, stepId, value) -> new state
//        getResults(records, state)    -> exact / alternatives / bundles
// ---------------------------------------------------------------------------

/* ----------------------------- normalisation ----------------------------- */

function slug(v) {
  return String(v == null ? '' : v)
    .trim()
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function toList(v) {
  if (v == null || v === '') return [];
  // Accepts arrays (Tags fields) or comma-separated text ("busy-mind, restless-body").
  const arr = Array.isArray(v) ? v : String(v).split(',');
  return arr.map(slug).filter(Boolean);
}

function allFilterFields(config) {
  const fields = new Set(['focus', 'guidanceType', 'soundCategory', 'specificSound', 'techniques']);
  Object.values(config.journeys).forEach((j) => j.steps.forEach((s) => fields.add(s.field)));
  return [...fields];
}

function wixImageToUrl(u) {
  // wix:image://v1/<mediaId>/<name>#... -> https://static.wixstatic.com/media/<mediaId>
  const m = /^wix:image:\/\/v1\/([^/#]+)/.exec(u || '');
  return m ? `https://static.wixstatic.com/media/${m[1]}` : u;
}

/** Turn a raw CMS-like row into the shape the engine uses. */
function normalizeRecord(raw, config = FINDER_CONFIG) {
  const rec = {
    id: raw._id || raw.id,
    title: raw.title || '',
    type: slug(raw.recordingType),
    url: raw.productUrl || '',
    imageUrl: wixImageToUrl(raw.imageUrl || raw.image || ''),
    audioUrl: raw.audioSampleUrl || '',
    price: raw.price == null || raw.price === '' ? null : Number(raw.price),
    durationMinutes: raw.durationMinutes == null || raw.durationMinutes === '' ? null : Number(raw.durationMinutes),
    durationLabel: raw.durationLabel || '',
    shortDescription: raw.shortDescription || '',
    why: raw.whyThisMatches || '',
    priority: Number(raw.priority) || 0,
    sortOrder: raw.sortOrder == null || raw.sortOrder === '' ? 9999 : Number(raw.sortOrder),
    isBundle: raw.isBundle === true,
    bundleTags: toList(raw.bundleTags),
    // finderEnabled is "on" unless explicitly false; isAvailable likewise.
    enabled: raw.finderEnabled !== false,
    available: raw.isAvailable !== false,
  };
  allFilterFields(config).forEach((f) => {
    rec[f] = toList(raw[f]);
  });
  return rec;
}

/* -------------------------------- labels --------------------------------- */

function humanise(value) {
  const s = String(value).replace(/-/g, ' ');
  return s.charAt(0).toUpperCase() + s.slice(1);
}

/** cmsOptions: [{ field, value, label, description, sortOrder }] from FinderOptions */
function makeLabeler(cmsOptions = [], config = FINDER_CONFIG) {
  const cms = {};
  cmsOptions.forEach((o) => {
    if (!o || !o.field || !o.value) return;
    cms[`${o.field}::${slug(o.value)}`] = o;
  });
  return {
    get(field, value) {
      const c = cms[`${field}::${value}`] || {};
      const d = (config.labels[field] && config.labels[field][value]) || {};
      const label = c.label || d.label || humanise(value);
      return {
        label,
        short: c.shortLabel || d.short || label,
        description: c.description || d.description || '',
      };
    },
    sortKey(field, value) {
      const c = cms[`${field}::${value}`];
      if (c && c.sortOrder != null && c.sortOrder !== '') return [0, Number(c.sortOrder)];
      const order = (config.order && config.order[field]) || [];
      const i = order.indexOf(value);
      return i >= 0 ? [1, i] : [2, 0];
    },
  };
}

/* ------------------------------- candidates ------------------------------ */

function journeyOf(state, config) {
  const j = config.journeys[state.journey];
  if (!j) throw new Error(`Unknown journey "${state.journey}"`);
  return j;
}

function basePool(records, journey, { bundles = false } = {}) {
  return records.filter(
    (r) => r.enabled && r.available && r.type === journey.recordingType && r.isBundle === bundles
  );
}

function filterByAnswers(pool, journey, answers) {
  let out = pool;
  journey.steps.forEach((s) => {
    const a = answers[s.id];
    if (a) out = out.filter((r) => r[s.field].includes(a));
  });
  return out;
}

function noteFor(journey, answers) {
  const notes = [];
  journey.steps.forEach((s) => {
    const a = answers[s.id];
    const rule = a && s.rules && s.rules[a];
    if (rule && rule.message) notes.push(rule.message);
  });
  return notes;
}

/* -------------------------------- next step ------------------------------ */

/**
 * state = { journey: 'sleep', answers: { focus: 'busy-mind', ... } }
 * Returns { done:false, step:{id,question,options[]}, number, notes } or
 *         { done:true, notes }.
 * Only options that still lead to at least one recording are returned, and a
 * step with fewer than 2 options is skipped, so a dead end is impossible.
 */
function getNextStep(records, state, cmsOptions = [], config = FINDER_CONFIG) {
  const journey = journeyOf(state, config);
  const labeler = makeLabeler(cmsOptions, config);
  const answers = state.answers || {};
  let pool = basePool(records, journey);
  let number = 1;

  for (const step of journey.steps) {
    const ans = answers[step.id];
    if (ans) {
      pool = pool.filter((r) => r[step.field].includes(ans));
      number += 1;
      continue;
    }
    if (step.requires && !answers[step.requires]) continue;

    const counts = new Map();
    pool.forEach((r) => r[step.field].forEach((v) => counts.set(v, (counts.get(v) || 0) + 1)));
    if (counts.size < 2) continue; // nothing to choose between -> skip

    const options = [...counts.entries()]
      .map(([value, count]) => {
        const l = labeler.get(step.field, value);
        return { value, label: l.label, description: l.description, count, _k: labeler.sortKey(step.field, value) };
      })
      .sort((a, b) => a._k[0] - b._k[0] || a._k[1] - b._k[1] || a.label.localeCompare(b.label))
      .map(({ _k, ...o }) => o);

    return {
      done: false,
      number,
      step: { id: step.id, question: step.question, help: step.help || '', options },
      notes: noteFor(journey, answers),
    };
  }
  return { done: true, notes: noteFor(journey, answers) };
}

/** Apply a visitor's choice (plus any implied answers) and return a NEW state. */
function chooseOption(records, state, stepId, value, cmsOptions = [], config = FINDER_CONFIG) {
  const journey = journeyOf(state, config);
  const next = getNextStep(records, state, cmsOptions, config);
  if (next.done || next.step.id !== stepId || !next.step.options.some((o) => o.value === value)) {
    throw new Error(`"${value}" is not a valid choice for step "${stepId}"`);
  }
  const answers = { ...(state.answers || {}), [stepId]: value };
  const step = journey.steps.find((s) => s.id === stepId);
  const rule = step.rules && step.rules[value];
  if (rule && rule.implies) {
    const pool = basePool(records, journey);
    Object.entries(rule.implies).forEach(([sid, v]) => {
      // Only apply an implied answer if it can't create an empty result set.
      if (filterByAnswers(pool, journey, { ...answers, [sid]: v }).length > 0) answers[sid] = v;
    });
  }
  return { journey: state.journey, answers };
}

/* --------------------------------- results ------------------------------- */

function soundText(rec, labeler) {
  if (rec.soundCategory.includes('voice-only') || rec.soundCategory.length === 0) return 'Voice only';
  const specifics = rec.specificSound.map((v) => labeler.get('specificSound', v).short.toLowerCase());
  const detail = specifics.length
    ? specifics.join(' and ')
    : rec.soundCategory.map((v) => labeler.get('soundCategory', v).short.toLowerCase()).join(' and ');
  return `Voice with ${detail}`;
}

function durationText(rec) {
  if (rec.durationLabel) return rec.durationLabel;
  if (rec.durationMinutes) return `${rec.durationMinutes} minutes`;
  return '';
}

function fallbackWhy(rec, answers, journey, labeler) {
  const parts = [];
  journey.steps.forEach((s) => {
    const a = answers[s.id];
    if (a) parts.push(labeler.get(s.field, a).short.toLowerCase());
  });
  return parts.length ? `Matches your choices: ${parts.join(', ')}.` : '';
}

function toCard(rec, labeler, journey, answers, config, extra = {}) {
  return {
    _id: rec.id,
    title: rec.title,
    url: rec.url,
    imageUrl: rec.imageUrl,
    audioUrl: rec.audioUrl,
    focus: rec.focus.map((v) => labeler.get('focus', v).short).join(' · '),
    techniques: rec.techniques.map((v) => labeler.get('techniques', v).label).join(' · '),
    sound: soundText(rec, labeler),
    duration: durationText(rec),
    price: rec.price == null ? '' : `${config.currency.prefix}${rec.price.toFixed(2)}`,
    // Generated fallback text only for exact matches; it would be untrue for alternatives.
    why: rec.why || (extra.difference ? '' : fallbackWhy(rec, answers, journey, labeler)),
    ...extra,
  };
}

function rank(a, b) {
  return (
    b.score - a.score ||
    b.rec.priority - a.rec.priority ||
    a.rec.sortOrder - b.rec.sortOrder ||
    a.rec.title.localeCompare(b.rec.title)
  );
}

/**
 * Returns { exact:[card], alternatives:[card], bundles:[card], notes:[string],
 *           browse:{label,url} }
 * exact        = matches every answered question (ranked, max limits.maxExact)
 * alternatives = differ on exactly ONE relaxable question; only shown when
 *                there are fewer than limits.minExactBeforeAlternatives exact
 *                matches. Never mixed into `exact`.
 * bundles      = separate list, never part of exact/alternatives.
 */
function getResults(records, state, cmsOptions = [], config = FINDER_CONFIG) {
  const journey = journeyOf(state, config);
  const labeler = makeLabeler(cmsOptions, config);
  const answers = state.answers || {};
  const L = config.limits;
  const criteria = journey.steps.filter((s) => answers[s.id]);

  const scored = basePool(records, journey).map((rec) => {
    const missed = [];
    let score = 0;
    criteria.forEach((s) => {
      if (rec[s.field].includes(answers[s.id])) score += s.weight;
      else missed.push(s);
    });
    // A refinement (e.g. specific sound) that only matters because its parent
    // question (sound) was already missed is not counted as a second difference.
    const missedIds = new Set(missed.map((m) => m.id));
    return { rec, score, missed: missed.filter((m) => !(m.requires && missedIds.has(m.requires))) };
  });

  const exactAll = scored.filter((x) => x.missed.length === 0).sort(rank);
  const exact = exactAll.slice(0, L.maxExact);
  const exactIds = new Set(exactAll.map((x) => x.rec.id));

  let alternatives = [];
  if (exactAll.length < L.minExactBeforeAlternatives) {
    let near = scored
      .filter((x) => x.missed.length === 1 && x.missed[0].relaxable && !exactIds.has(x.rec.id))
      .sort(rank);
    let fallbackLabel = null;
    if (exact.length === 0 && near.length === 0) {
      // Safety net (should not happen with dynamic options): closest recordings.
      near = scored.filter((x) => !exactIds.has(x.rec.id)).sort(rank);
      fallbackLabel = 'Closest available recording';
    }
    alternatives = near.slice(0, L.maxAlternatives).map((x) =>
      toCard(x.rec, labeler, journey, answers, config, {
        difference: fallbackLabel || (x.missed[0] && x.missed[0].differenceLabel) || 'Differs slightly from your choices',
      })
    );
  }

  // Bundles: separate pool, shown when they share a tag/value with the answers.
  const chosen = Object.values(answers);
  const bundles = basePool(records, journey, { bundles: true })
    .filter((b) => {
      if (chosen.length === 0) return true;
      const tags = new Set([...b.bundleTags, ...allFilterFields(config).flatMap((f) => b[f] || [])]);
      return chosen.some((v) => tags.has(v));
    })
    .sort((a, b) => b.priority - a.priority || a.sortOrder - b.sortOrder || a.title.localeCompare(b.title))
    .slice(0, L.maxBundles)
    .map((b) => toCard(b, labeler, journey, answers, config, { isBundle: true }));

  return {
    exact: exact.map((x) => toCard(x.rec, labeler, journey, answers, config)),
    alternatives,
    bundles,
    notes: noteFor(journey, answers),
    browse: { label: journey.browseLabel, url: journey.browseUrl },
    summary: criteria.map((s) => labeler.get(s.field, answers[s.id]).label),
  };
}

/* --------------------------------- audit --------------------------------- */

/** Data-health report for the site owner. Returns [{ id, title, issue }]. */
function auditRecords(records, cmsOptions = [], config = FINDER_CONFIG) {
  const issues = [];
  const known = (field, v) =>
    (config.labels[field] && config.labels[field][v]) ||
    cmsOptions.some((o) => o.field === field && slug(o.value) === v);
  records.forEach((r) => {
    const add = (issue) => issues.push({ id: r.id, title: r.title, issue });
    if (!r.enabled) return;
    const journey = Object.values(config.journeys).find((j) => j.recordingType === r.type);
    if (!journey) add(`recordingType "${r.type}" is not one of: ${Object.values(config.journeys).map((j) => j.recordingType).join(', ')}`);
    if (!r.url) add('No product URL (and no linked product).');
    if (!r.isBundle) {
      if (journey) {
        journey.steps.forEach((s) => {
          if (r[s.field].length === 0) add(`"${s.field}" is empty, so this recording can't be reached through the "${s.id}" question.`);
        });
      }
      if (!r.why) add('"Why this matches" is empty (a generic sentence will be shown).');
    }
    if (r.price == null) add('No price.');
    allFilterFields(config).forEach((f) =>
      r[f].forEach((v) => {
        if (!known(f, v)) add(`Value "${v}" in "${f}" has no label yet (a generated one is used). Add it to FinderOptions if you want a custom label.`);
      })
    );
  });
  return issues;
}

